INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5554783, 801707, 57460, '<td valign="top">Nice smooth waterfall, but I have seen smooth water alot here on DPC - but you do show a unique interpretation.  Good job.</td>', 'Nice smooth waterfall, but I have seen smooth water alot here on DPC - but you do show a unique interpretation.  Good job.', '2009-07-01 22:31:39.000000', NULL, 1),
(5554789, 801742, 57460, '<td valign="top">Wow - is that a jelly fish?  Great capture.  I think overall it is a little dark - maybe some levels or curves adjustment would help make this pop a little more.  But bonus points for the unique capture!</td>', 'Wow - is that a jelly fish?  Great capture.  I think overall it is a little dark - maybe some levels or curves adjustment would help make this pop a little more.  But bonus points for the unique capture!', '2009-07-01 22:33:54.000000', NULL, 1),
(5554792, 802121, 57460, '<td valign="top">Cute baby bird - I am loving his mohawk!</td>', 'Cute baby bird - I am loving his mohawk!', '2009-07-01 22:35:18.000000', NULL, 1),
(5554798, 802066, 57460, '<td valign="top">Interesting interpretation!  The gray on the left, and the tree in the front is a little distracting though, but otherwise Good job!</td>', 'Interesting interpretation!  The gray on the left, and the tree in the front is a little distracting though, but otherwise Good job!', '2009-07-01 22:37:13.000000', NULL, 1),
(5554800, 801968, 38162, '<td valign="top">windy title aside, excellent abstract</td>', 'windy title aside, excellent abstract', '2009-07-01 22:37:14.000000', NULL, 1),
(5554854, 801889, 57460, '<td valign="top">If he is blind with a chainsaw - it looks like he might cut off his own arm! :)  I think your post-processing works very well here - it makes the hand look almost 3D!</td>', 'If he is blind with a chainsaw - it looks like he might cut off his own arm! :)  I think your post-processing works very well here - it makes the hand look almost 3D!', '2009-07-01 22:52:23.000000', NULL, 1),
(5554862, 801485, 57460, '<td valign="top">I think this fits the challenge - I don''t think I have seen a picture of a jump rope on here - but I feel the photo is lacking something more of interest.  But I do really like the DOF - I am a fan of shallow DOF.</td>', 'I think this fits the challenge - I don''t think I have seen a picture of a jump rope on here - but I feel the photo is lacking something more of interest.  But I do really like the DOF - I am a fan of shallow DOF.', '2009-07-01 22:53:59.000000', NULL, 1),
(5555089, 802024, 54645, '<td valign="top">Love those smiles! I always enjoy your topaz processing. &lt;no vote&gt;</td>', 'Love those smiles! I always enjoy your topaz processing. <no vote>', '2009-07-02 01:19:15.000000', NULL, 1),
(5555090, 801892, 54645, '<td valign="top">What a fun photograph. The reflections give a lot of depth, giving the sense of the man behind the curtain...the Wizard of Oz.</td>', 'What a fun photograph. The reflections give a lot of depth, giving the sense of the man behind the curtain...the Wizard of Oz.', '2009-07-02 01:19:17.000000', NULL, 1),
(5555107, 802067, 103534, '<td valign="top">missing the "wow" factor for me.</td>', 'missing the "wow" factor for me.', '2009-07-02 02:01:28.000000', NULL, 1),
(5555121, 802123, 103534, '<td valign="top">Brave....very, very brave.  But, definately hit the nail on the head as far as theme goes. 10.</td>', 'Brave....very, very brave.  But, definately hit the nail on the head as far as theme goes. 10.', '2009-07-02 02:32:53.000000', NULL, 1),
(5555122, 802094, 103534, '<td valign="top">Meets challenge well.</td>', 'Meets challenge well.', '2009-07-02 02:35:05.000000', NULL, 1),
(5555133, 802076, 103534, '<td valign="top">Funny.  Definately works for this challenge.</td>', 'Funny.  Definately works for this challenge.', '2009-07-02 03:15:00.000000', NULL, 1),
(5555137, 802032, 103534, '<td valign="top">Fits challenge well.  No block in creativity for you.  Well done.</td>', 'Fits challenge well.  No block in creativity for you.  Well done.', '2009-07-02 03:36:07.000000', NULL, 1),
(5555161, 801407, 73329, '<td valign="top">JP Patches!</td>', 'JP Patches!', '2009-07-02 05:02:14.000000', NULL, 1),
(5555189, 800657, 103142, '<td valign="top">It might not have been done before, but I''m sorry, I don''t find it very interesting... and it''s a little tilted.</td>', 'It might not have been done before, but I''m sorry, I don''t find it very interesting... and it''s a little tilted.', '2009-07-02 06:54:29.000000', NULL, 1),
(5555190, 800472, 103142, '<td valign="top">Might have been a tad more interesting from the side... Also, it looks a little under exposed? Interesting worm though!</td>', 'Might have been a tad more interesting from the side... Also, it looks a little under exposed? Interesting worm though!', '2009-07-02 06:54:33.000000', NULL, 1),
(5555194, 802132, 103142, '<td valign="top">I really like the shot --  The colors look a little dull and lifeless because we know just how bright and wonderful they can be. I think this would have been a spectacular shot if you lightened it and brought the colors out a lot more.</td>', 'I really like the shot --  The colors look a little dull and lifeless because we know just how bright and wonderful they can be. I think this would have been a spectacular shot if you lightened it and brought the colors out a lot more.', '2009-07-02 07:00:29.000000', NULL, 1),
(5555195, 800835, 103142, '<td valign="top">Can''t say that I''ve seen it before, though I''m a little tired of light bulbs, it is a different take on it. However, if you would have had a lit light bulb in water...</td>', 'Can''t say that I''ve seen it before, though I''m a little tired of light bulbs, it is a different take on it. However, if you would have had a lit light bulb in water...', '2009-07-02 07:02:04.000000', NULL, 1),
(5555196, 801584, 103142, '<td valign="top">Interesting idea... It seems a tad dark; it might be more interesting lightened a little (imo).</td>', 'Interesting idea... It seems a tad dark; it might be more interesting lightened a little (imo).', '2009-07-02 07:02:09.000000', NULL, 1),
(5555197, 802054, 103142, '<td valign="top">I''m afraid that I might be misinterpreting this one--but it looks like a spiral staircase from the top down... Which has been done before.<br/> <br/>It''s very interesting, and well done. But I''m afraid it''s been seen before.<br/> <br/>(I''m sorry if I''m wrong about it...)</td>', 'I''m afraid that I might be misinterpreting this one--but it looks like a spiral staircase from the top down... Which has been done before. It''s very interesting, and well done. But I''m afraid it''s been seen before. (I''m sorry if I''m wrong about it...)', '2009-07-02 07:02:13.000000', NULL, 1),
(5555198, 801780, 103142, '<td valign="top">Very nice picture, but people laying side by side has been done before -- here''s one example, but I''ve seen others as well. <a href="//www.dpchallenge.com/image.php?IMAGE_ID=448983" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/616/120/Copyrighted_Image_Reuse_Prohibited_448983.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/616/120/Copyrighted_Image_Reuse_Prohibited_448983.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/616/120/Copyrighted_Image_Reuse_Prohibited_448983.jpg"/></a>, sorry... Wonderful shot, though!</td>', 'Very nice picture, but people laying side by side has been done before -- here''s one example, but I''ve seen others as well. , sorry... Wonderful shot, though!', '2009-07-02 07:02:18.000000', NULL, 1),
(5555199, 802063, 103142, '<td valign="top">I''m sorry--I think I must be missing something. there have been many pictures of piles of rocks. I''m sorry I''m not getting it--feel free to pm me and tell me how stupid I''m being :)</td>', 'I''m sorry--I think I must be missing something. there have been many pictures of piles of rocks. I''m sorry I''m not getting it--feel free to pm me and tell me how stupid I''m being :)', '2009-07-02 07:02:24.000000', NULL, 1),
(5555200, 801763, 103142, '<td valign="top">Most shots on DPC have clouds and something else, but there have been shots with just clouds. I''m sorry, but imo, it''s been seen before.</td>', 'Most shots on DPC have clouds and something else, but there have been shots with just clouds. I''m sorry, but imo, it''s been seen before.', '2009-07-02 07:02:26.000000', NULL, 1),
(5555201, 801951, 103142, '<td valign="top">Very well done. Glass block windows have been seen on DPC -- <a href="//www.dpchallenge.com/image.php?IMAGE_ID=273054" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/426/120/Copyrighted_Image_Reuse_Prohibited_273054.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/426/120/Copyrighted_Image_Reuse_Prohibited_273054.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/426/120/Copyrighted_Image_Reuse_Prohibited_273054.jpg"/></a>, but only in one or two shots. So while it''s not a NEVER been seen, it''s at least rare!</td>', 'Very well done. Glass block windows have been seen on DPC -- , but only in one or two shots. So while it''s not a NEVER been seen, it''s at least rare!', '2009-07-02 07:02:31.000000', NULL, 1),
(5555202, 802010, 103142, '<td valign="top">Extremely well done photo, but gender bending has been done before -- maybe not with those specific people :D</td>', 'Extremely well done photo, but gender bending has been done before -- maybe not with those specific people :D', '2009-07-02 07:02:55.000000', NULL, 1),
(5555204, 802076, 103142, '<td valign="top">Spectacular idea!! I do agree that the corn looks nasty at the end -- sorry, I should have given you a better piece of corn to work with. I just thought we''d eat the good stuff the next day...! I think you did an awesome job on this, and I like the angle you chose. It''s exciting that it''s going to be your PB!</td>', 'Spectacular idea!! I do agree that the corn looks nasty at the end -- sorry, I should have given you a better piece of corn to work with. I just thought we''d eat the good stuff the next day...! I think you did an awesome job on this, and I like the angle you chose. It''s exciting that it''s going to be your PB!', '2009-07-02 07:07:27.000000', NULL, 1),
(5555205, 802083, 103142, '<td valign="top">Interesting shot. Since the balloons are your main subject, I would have lightened the bottom part of the picture a tad--seems a little dark... Certainly haven''t seen them before!</td>', 'Interesting shot. Since the balloons are your main subject, I would have lightened the bottom part of the picture a tad--seems a little dark... Certainly haven''t seen them before!', '2009-07-02 07:08:24.000000', NULL, 1),
(5555207, 801824, 103142, '<td valign="top">While the lines between the windows do disappear and leave just stripes, it really doesn''t seem all that unique, IMO. (sorry). It''s too similar to shots like this <a href="//www.dpchallenge.com/image.php?IMAGE_ID=236971" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/383/120/Copyrighted_Image_Reuse_Prohibited_236971.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/383/120/Copyrighted_Image_Reuse_Prohibited_236971.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/383/120/Copyrighted_Image_Reuse_Prohibited_236971.jpg"/></a>. I do like the zebra''s tail, however!</td>', 'While the lines between the windows do disappear and leave just stripes, it really doesn''t seem all that unique, IMO. (sorry). It''s too similar to shots like this . I do like the zebra''s tail, however!', '2009-07-02 07:11:57.000000', NULL, 1),
(5555208, 801443, 103142, '<td valign="top">Whether or not is has been done before, imo it doesn''t hold much interest... sorry!</td>', 'Whether or not is has been done before, imo it doesn''t hold much interest... sorry!', '2009-07-02 07:14:55.000000', NULL, 1),
(5555210, 800768, 103142, '<td valign="top">I find this very interesting -- can''t tell if it''s been done before, because I''m not even sure what to look up :D<br/> <br/>But it''s a very interesting shot.</td>', 'I find this very interesting -- can''t tell if it''s been done before, because I''m not even sure what to look up :D But it''s a very interesting shot.', '2009-07-02 07:15:52.000000', NULL, 1),
(5555349, 802132, 107943, '<td valign="top">is that what I think it is? ha</td>', 'is that what I think it is? ha', '2009-07-02 10:34:12.000000', NULL, 1),
(5555356, 802030, 61961, '<td valign="top">I suspect this is some sort of critter on a plate, but I can''t really tell what I''m seeing.  I think color might have served this better, and perhaps a deeper DOF, or at least focus on the second or this thingy rather than the one in the foreground.</td>', 'I suspect this is some sort of critter on a plate, but I can''t really tell what I''m seeing.  I think color might have served this better, and perhaps a deeper DOF, or at least focus on the second or this thingy rather than the one in the foreground.', '2009-07-02 10:43:46.000000', NULL, 1),
(5555359, 801788, 61961, '<td valign="top">That''s Rod Taylor in the photo, isn''t it?</td>', 'That''s Rod Taylor in the photo, isn''t it?', '2009-07-02 10:45:17.000000', NULL, 1),
(5555360, 802010, 61961, '<td valign="top">For some reason I find this more off-putting than funny, but I''m forced to give you high points for technical competence, originality, and impact!</td>', 'For some reason I find this more off-putting than funny, but I''m forced to give you high points for technical competence, originality, and impact!', '2009-07-02 10:51:40.000000', NULL, 1),
