(5557104, 802064, 57460, '<td valign="top">Very interesting - the rubber glove makes it even more creepy.  I like it.</td>', 'Very interesting - the rubber glove makes it even more creepy.  I like it.', '2009-07-03 00:16:51.000000', NULL, 1),
(5557106, 800789, 50641, '<td valign="top">ha!</td>', 'ha!', '2009-07-03 00:17:08.000000', NULL, 1),
