INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5557219, 802123, 50641, '<td valign="top">a wow from me!!</td>', 'a wow from me!!', '2009-07-03 00:43:57.000000', NULL, 1),
(5557221, 801951, 57460, '<td valign="top">Very abstract and interesting.  Very good job at aligning and centering the glass blocks - it makes it appear as if you have four different photos.  Good job!</td>', 'Very abstract and interesting.  Very good job at aligning and centering the glass blocks - it makes it appear as if you have four different photos.  Good job!', '2009-07-03 00:44:22.000000', NULL, 1),
(5557222, 801356, 50641, '<td valign="top">engaging abstract</td>', 'engaging abstract', '2009-07-03 00:44:22.000000', NULL, 1),
(5557223, 800844, 50641, '<td valign="top">good job</td>', 'good job', '2009-07-03 00:44:32.000000', NULL, 1),
(5557225, 801861, 50641, '<td valign="top">how did you know i love dead fish heads</td>', 'how did you know i love dead fish heads', '2009-07-03 00:44:50.000000', NULL, 1),
(5557227, 801781, 81213, '<td valign="top">I seriously can''t tell whats going on here... Creative, but everything id blurred out, the image is pixelated and grainy, you cant tell whats going on, the picture has no sign of incorporating anything that has to do with MJ, you can barely make out a guitar (MJ was mainly a singer and dancer, don''t ya think that''s what hed want us to remember him for)... Good effort, bad photo, sorry!</td>', 'I seriously can''t tell whats going on here... Creative, but everything id blurred out, the image is pixelated and grainy, you cant tell whats going on, the picture has no sign of incorporating anything that has to do with MJ, you can barely make out a guitar (MJ was mainly a singer and dancer, don''t ya think that''s what hed want us to remember him for)... Good effort, bad photo, sorry!', '2009-07-03 00:44:58.000000', NULL, 1),
(5557228, 802064, 81213, '<td valign="top">This is great, I''m not sure if the motion blur was created in photoshop or not but this is just a well-composed image by someone who obviously knows what they are doing. I only wish I could say the same for others in this challenge (I was really looking forward to it) Anyway, the off-center doll-head helps mak room for the glove (taped to its neck?) and leaves some white space to the left that is just icing on the cake.</td>', 'This is great, I''m not sure if the motion blur was created in photoshop or not but this is just a well-composed image by someone who obviously knows what they are doing. I only wish I could say the same for others in this challenge (I was really looking forward to it) Anyway, the off-center doll-head helps mak room for the glove (taped to its neck?) and leaves some white space to the left that is just icing on the cake.', '2009-07-03 00:45:02.000000', NULL, 1),
